ALTER TABLE public.comm_reactions ADD CONSTRAINT comm_reaction_unique UNIQUE(message_id,user_id,reaction);
CREATE OR REPLACE FUNCTION public.comm_access(p_conversation uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM comm_conversations c WHERE c.id=p_conversation AND (EXISTS(SELECT 1 FROM comm_participants p JOIN comm_org_members m ON m.org_id=p.org_id AND m.user_id=p.user_id WHERE p.conversation_id=c.id AND p.user_id=auth.uid()) OR (c.kind='channel' AND NOT c.private AND comm_member(c.org_id))) AND (c.harvest_id IS NULL OR EXISTS(SELECT 1 FROM harvests h WHERE h.id=c.harvest_id AND (h.farmer_id=auth.uid() OR is_staff(auth.uid())))) AND (c.request_id IS NULL OR EXISTS(SELECT 1 FROM trade_requests r WHERE r.id=c.request_id AND (comm_member(r.org_id) OR comm_member(r.partner_org_id))))) $$;
CREATE FUNCTION public.comm_accept_invitation(p_token uuid,p_org uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i comm_invitations; c comm_conversations; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO i FROM comm_invitations WHERE token=p_token AND accepted_by IS NULL AND expires_at>now() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Invitation expired or already accepted'; END IF; IF i.conversation_id IS NULL THEN INSERT INTO comm_org_members(org_id,user_id,role) VALUES(i.org_id,auth.uid(),'member') ON CONFLICT DO NOTHING; ELSE SELECT * INTO c FROM comm_conversations WHERE id=i.conversation_id; IF c.kind NOT IN ('direct','group') OR c.harvest_id IS NOT NULL OR c.request_id IS NOT NULL OR NOT comm_member(p_org) THEN RAISE EXCEPTION 'External invitation unavailable'; END IF; INSERT INTO comm_participants(conversation_id,user_id,org_id) VALUES(c.id,auth.uid(),p_org) ON CONFLICT DO NOTHING; END IF; UPDATE comm_invitations SET accepted_by=auth.uid() WHERE id=i.id; RETURN jsonb_build_object('id',coalesce(i.conversation_id,i.org_id)); END $$;
REVOKE ALL ON FUNCTION public.comm_accept_invitation(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.comm_accept_invitation(uuid,uuid) TO authenticated;